from pathlib import Path
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from pypdf import PdfReader
import shutil
root=Path(__file__).resolve().parents[2]
out=root/'output/pdf';out.mkdir(parents=True,exist_ok=True)
web=root/'website/assets/documents';web.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='BodyAudit',fontName='Helvetica',fontSize=10,leading=15,spaceAfter=9));styles.add(ParagraphStyle(name='KickerAudit',fontSize=9,leading=13,textColor=colors.HexColor('#14736b'),spaceAfter=12));styles['Title'].fontSize=25;styles['Title'].leading=30
P=lambda s:Paragraph(s,styles['BodyAudit'])
def table(rows,widths):
 t=Table([[P(str(c)) for c in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e1eeed')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#bccfd5')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),5)]));return t
def heading(text):return Paragraph(text,styles['Heading2'])
def frame(canvas,doc):
 canvas.saveState();w,h=doc.pagesize;canvas.setFillColor(colors.HexColor('#123950'));canvas.rect(0,h-12,w,12,fill=1,stroke=0);canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#5c7382'));canvas.drawString(45,h-35,'CONTINUOUS RISK ASSURANCE / TEACHING EVIDENCE');canvas.drawString(45,25,'SIMULATED COMPANY REPORT - NOT REAL CLIENT INFORMATION');canvas.drawRightString(w-45,25,str(doc.page));canvas.restoreState()
for org,name in [('exporter','PT Samudra Pangan Ekspor'),('finance','PT Cakrawala Pembiayaan UKM')]:
 for kind in ['internal','audit']:
  audit=kind=='audit';code='AUD-2025-03' if audit else 'INT-2025-04';date='8 April 2025' if audit else '7 April 2025';title='Internal audit: approval discipline and assurance gaps' if audit else 'Management operating review: exposure and control exceptions'
  story=[Paragraph('SIMULATED / HISTORICAL EXERCISE',styles['KickerAudit']),Paragraph(title,styles['Title']),P(name),P(f'{code} | Prepared {date} | Distribution: Risk Committee and process owners'),heading('Executive summary')]
  if audit:
   story+=[P('Internal Audit reviewed 40 selected change and override files. Six files did not contain an independent approval record in the evidence pack supplied to the team. This is an evidence exception, not a finding that approval never occurred and not an allegation of fraud. The purposive sample is not designed to estimate the population exception rate.'),P('For the exporter, the review concerns price concessions and supplier changes; missing approval evidence could weaken margin protection and supplier assurance. For the finance company, the relevant records are underwriting and identity overrides; gaps could weaken loan approval discipline and customer-verification controls.'),P('Three findings address incomplete approval references, inconsistent follow-up ownership and insufficient independent verification of closure. The risk owner should confirm source completeness before revising the assessment. AI summaries or scores are suggestions requiring human judgement.')]
  else:
   story+=[P('Management identifies increased exposure in the April 2025 historical scenario. External trade-policy uncertainty is considered alongside internal exceptions. News does not establish a company loss: confirm product coverage, customer commitments and the relevant contractual terms.'),P('Exporter scenario: 45% of revenue depends on US buyers. Operations recorded eight temperature excursions in 120 shipments; four records have no documented disposition. Two suppliers account for 64% of critical inputs. Finance scenario: 35% of loans finance export manufacturers; management recorded three service outages and unresolved identity-verification exceptions. These fictional facts warrant investigation rather than an automatic risk-score increase.'),P('The operating review asks Commercial/Credit, Operations and Compliance to reconcile exceptions, designate owners and provide original evidence. Decisions on risk scores and mitigation remain with the accountable risk owner.')]
  story += [heading('Decisions requested'),P('1. Accept or reject each source for each linked risk, explaining the assessment.<br/>2. Review likelihood and impact against the objective and current controls.<br/>3. If above tolerance 12, assign a mitigation with a due date and expected effect.<br/>4. Treat mitigation effects as planned until supported by effectiveness evidence.'),heading('Evidence status'),P('All company names, records, tables and findings in this report are fictional teaching data. There is no client attribution. The two external ANTARA stories replay the same April 2025 policy event and must not be counted as independent evidence of realised losses.'),PageBreak()]
  story += [heading('2. Scope, method and data dictionary'),P('Review period: 1 January to 31 March 2025, with management discussion on 7-8 April. The pack combines operating extracts, sampled approval files and a follow-up register. Internal data have not been independently validated outside this exercise.'),table([['Evidence ID','Record','Method / limitation'],['R01','Operating indicator extract','Read the definitions and reconcile to source transactions.'],['R02','40 purposively selected files','Inspect the supplied approval references; selection is non-statistical.'],['R03','Exception follow-up log','Check owner, due date and closure evidence.'],['R04','Management meeting notes','Management representations require corroboration.']],[65,175,265]),heading('Measures used'),P('Likelihood is an ordinal 1-5 assessment; impact is an ordinal 1-5 consequence assessment. Their product is a teaching matrix score, not a probability or financial forecast. Risk tolerance is set at 12 for this exercise. A planned target is calculated after proposed reductions, with dimensions floored at 1.'),P('The evidence pack distinguishes a missing record from an absent control, an exception from its cause, and an action plan from proven effectiveness. A reviewer should challenge any summary that collapses these distinctions.'),heading('Linkage to registered risks'),P('Primary risk: commercial/credit-control exposure. Secondary risk: operational continuity or cold-chain quality. Third risk: supplier reliability or customer identity fraud. A document may inform more than one risk, but each risk requires its own relevance decision and response.'),PageBreak()]
  if audit:
   population='pricing and supplier-change' if org=='exporter' else 'underwriting and identity-override'
   rows=[['Test area','Selected files','Evidence result'],['Independent approval reference','40 '+population+' files','6 files: approval record not in supplied pack'],['Approval timing','34 traceable references','Compare authorisation with activation time'],['Follow-up accountability','6 exception records','4 have no documented closure owner'],['Closure verification','3 records labelled complete','2 have no independent retest record']]
   findings=[('Finding A01 / Approval references','Six selected files contain a change or override entry without an independently traceable approval reference in the pack. Obtain the missing records and compare timestamps with activation. Until then, record incomplete evidence. Do not infer intent, authorisation failure across all branches or population prevalence.'),('Finding A02 / Follow-up accountability','Four exception records lack a documented closure owner or substantiated disposition. This may delay corrective action and reduce the reliability of the operating dashboard. Check whether responsibility is defined elsewhere before concluding that no owner exists.'),('Finding A03 / Closure verification','Two of three records marked complete lack an independent effectiveness check. Distinguish activity completion from restoration of control effectiveness. Retest the relevant preventive and detective checks.')]
  elif org=='exporter':
   rows=[['Operating measure','Result / denominator','Management interpretation'],['US buyer concentration','45% of total revenue','Buyer confirmations and pricing need review'],['Temperature excursions','8 / 120 shipments','Four records lack a documented disposition'],['Critical-input concentration','64% across two suppliers','Validate alternative capacity and lead times'],['Open buyer confirmations','5 / 18 US buyers','Forecast exposure, not cancelled orders'],['Recovery tests','1 / 3 logistics providers','Obtain the remaining recovery evidence']]
   findings=[('Observation O01 / Order visibility','Five of 18 US buyers have not reconfirmed the next-quarter forecast after the tariff announcement. This affects forecast confidence; it is not a cancellation or a realised loss. Commercial should obtain dated responses and reconcile them with contractual commitments.'),('Observation O02 / Cold-chain exceptions','Operations logged eight excursions across 120 shipments. Four records have no documented product disposition. Inspect duration, temperature, batch sensitivity and quality-release evidence before concluding damage. Assign a disposition owner for each unresolved record.'),('Observation O03 / Supply resilience','Two suppliers account for 64% of critical inputs. Alternative capacity and recovery evidence are incomplete. Confirm approved substitute suppliers, lead times and quality checks before relying on the continuity plan.')]
  else:
   rows=[['Operating measure','Result / denominator','Management interpretation'],['Export-manufacturer loans','35% of loan portfolio','Review borrower cash flow and concentration'],['Core-service outages','3 incidents in quarter','42, 65 and 95 minutes; reconcile impact'],['Identity-verification cases','2 unresolved / 60 reviewed','Missing records require investigation'],['Approval overrides','7 / 40 reviewed files','Reconcile authority and approval timestamps'],['Disaster-recovery test','1 / 2 planned tests','Outstanding test is not proof of failure']]
   findings=[('Observation O01 / Borrower exposure','Export manufacturers account for 35% of the loan portfolio. Borrower forecasts may become less reliable after the trade-policy announcement. Reassess cash-flow assumptions and sector concentration. The news alone does not establish higher defaults or an underwriting breach.'),('Observation O02 / Service availability','Three core-service incidents lasted 42, 65 and 95 minutes. Reconcile customer backlogs, failed jobs and recovery logs with the incident register. An outage count alone cannot establish financial loss or the effectiveness of recovery controls.'),('Observation O03 / Identity exceptions','Two of 60 reviewed customer files have unresolved verification references. Seven approval overrides also require authority reconciliation. Obtain the original records before classifying the issues as control failures. These observations do not establish impersonation or fraud.')]
  story += [heading('3. Detailed results and interpretation'),table(rows,[155,165,185])]
  for finding,text in findings:story += [heading(finding),P(text)]
  story += [PageBreak()]
  story += [heading('4. Risk implications and management response'),P('Assessment workshop proposal: discuss whether likelihood should rise from 3 to 4 for the primary risk. For other risks, assess both exposure and control evidence. This proposal is illustrative and must not replace the assessment of the risk owner. A score of 16 exceeds the teaching tolerance of 12.'),table([['Action','Accountable unit','Evidence of completion'],['Reconcile approvals and timestamps','Commercial / Credit Risk','Linked source records and reviewer sign-off'],['Assign unresolved exception owners','Operations','Disposition log with target dates'],['Strengthen source completeness checks','Compliance / Quality','Reconciled population and exception counts'],['Retest preventive controls','Independent assurance','Test results and limitations'],['Monitor actual outcome','Risk owner','Trend, residual assessment and rationale']],[180,130,195]),heading('Planned effect and review'),P('A mitigation may reduce likelihood by 1 while leaving impact unchanged. For L4 x I4, the planned target becomes L3 x I4 = 12. The current assessment remains 16 until effectiveness is demonstrated. Enter title, unit in charge, due date, dimension effects and explanation in the application.'),heading('Management comments'),P('Management accepts the need to validate source completeness and assign owners. The specific score, due dates and mitigation plan are intentionally left for the participant acting as risk owner. This is not an actual management commitment.'),PageBreak()]
  annex=[['Case','Reference','Observation','Status']]+[[f'EX-{i:02}',f'R02 / file {i*5+1:02}','Approval record not supplied','Clarification required'] for i in range(1,7)]
  story += [heading('5. Appendix / traceability and source notes'),table(annex,[55,100,215,135]),heading('Reconciliation checklist'),P('Confirm the extract date and completeness; obtain missing originals; match IDs and timestamps; separate duplicates; record accept/reject decisions for each linked risk; retain the reason for the final score; approve and monitor the mitigation. Do not overwrite the original evidence with an AI summary.'),heading('External context'),P('ANTARA, 3 April 2025: announcement of US reciprocal tariffs and the Indonesian policy response. These are historical event reports, not current tariff guidance or proof of company exposure. Two stories about the same event are correlated sources.'),P('<link href="https://jabar.antaranews.com/berita/594405/indonesia-kena-kenaikan-tarif-as-32-persen" color="#006e9c">Original announcement article</link><br/><link href="https://jatim.antaranews.com/berita/902409/indonesia-siapkan-langkah-strategis-respons-kebijakan-tarif-resiprokal-as" color="#006e9c">Original response article</link>'),heading('Use limitations'),P('For learning only. No personal records, real transactions or confidential company material are included. Prepared AI scoring and mitigation suggestions are transparent teaching aids. No live model, real-time news capture or causal inference is claimed.')]
  file=out/f'cra-{kind}-{org}.pdf';SimpleDocTemplate(str(file),pagesize=(595.28,841.89),rightMargin=45,leftMargin=45,topMargin=60,bottomMargin=50,title=title,author='SIGNAL training / fictional evidence').build(story,onFirstPage=frame,onLaterPages=frame)
  pages=len(PdfReader(file).pages);assert pages==5,(file,pages);shutil.copyfile(file,web/file.name);print(file.name,pages)
